extern crate std;
use super::*;
use std::vec::Vec;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

fn check(key: &str, nonce: &str, aad: &str, pt: &str, ct_tag: &str) {
    let key: [u8; 32] = unhex(key).try_into().unwrap();
    let nonce: [u8; 12] = unhex(nonce).try_into().unwrap();
    let (aad, pt, want) = (unhex(aad), unhex(pt), unhex(ct_tag));
    let k = key_from_bytes(&key);
    let mut data = pt.clone();
    let tag = seal(&k, &nonce, &aad, &mut data);
    let (ct, want_tag) = want.split_at(want.len() - 16);
    assert_eq!(data, ct);
    assert_eq!(tag.to_vec(), want_tag);
    let mut back = data.clone();
    assert!(open(&k, &nonce, &aad, &mut back, &tag));
    assert_eq!(back, pt);
    // any change to the ciphertext, the associated data, the nonce or the tag is refused
    if !data.is_empty() {
        let mut bad = data.clone();
        bad[data.len() / 2] ^= 1;
        assert!(!open(&k, &nonce, &aad, &mut bad, &tag));
    }
    let mut c = data.clone();
    let mut aad2 = aad.clone();
    aad2.push(0);
    assert!(!open(&k, &nonce, &aad2, &mut c, &tag));
    let mut nonce2 = nonce;
    nonce2[0] ^= 1;
    assert!(!open(&k, &nonce2, &aad, &mut c, &tag));
    let mut tag2 = tag;
    tag2[15] ^= 0x80;
    assert!(!open(&k, &nonce, &aad, &mut c, &tag2));
    assert_eq!(c, data, "a refused message is left as it was");
}

#[test]
fn vector_rfc() {
    check(
        "808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f",
        "070000004041424344454647",
        "50515253c0c1c2c3c4c5c6c7",
        "4c616469657320616e642047656e746c656d656e206f662074686520636c617373206f66202739393a204966204920636f756c64206f6666657220796f75206f6e6c79206f6e652074697020666f7220746865206675747572652c2073756e73637265656e20776f756c642062652069742e",
        "d31a8d34648e60db7b86afbc53ef7ec2a4aded51296e08fea9e2b5a736ee62d63dbea45e8ca9671282fafb69da92728b1a71de0a9e060b2905d6a5b67ecd3b3692ddbd7f2d778b8c9803aee328091b58fab324e4fad675945585808b4831d7bc3ff4def08e4b7a9de576d26586cec64b61161ae10b594f09e26a7e902ecbd0600691",
    );
}

